  v_product_id   uuid;
  v_variant_id   uuid;
  v_po_item_id   uuid;
  v_quantity     numeric;
  v_unit_cost    numeric;
  v_param_hash   text;
  v_existing     jsonb;
  v_seen_po_items uuid[] := ARRAY[]::uuid[];
